      for (auto leftTree : leftSubtrees) {
        for (auto rightTree : rightSubtrees) {
          TreeNode *root = new TreeNode(i);
          root->left = leftTree;
          root->right = rightTree;
          result.push_back(root);
        }
      }
    }
    return result;
  }
};

